  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : 26 + (L.charCodeAt(0) - 65) * 26 + (L.charCodeAt(1) - 64)
  return { col, row }
}
const colName = (c) => c <= 26 ? String.fromCharCode(64 + c) : String.fromCharCode(65 + Math.floor((c - 27) / 26)) + String.fromCharCode(65 + ((c - 27) % 26))
const key = (a) => a.col * 1000 + a.row
const name = (k) => colName(Math.floor(k / 1000)) + (k % 1000)

// ---- sheet reading
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
lines.forEach((raw, i) => {
  const s = raw.replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') return
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(s)
  const a = parseAddr(m[1])
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${m[1]}`)
  const k = key(a)
  if (cells.has(k)) fail(`error: line ${i + 1}: cell ${m[1]} is declared twice`)
  cells.set(k, m[2])
})

// ---- formula parsing
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(s.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

function parse(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const bad = new Error('grammar')
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  function cmp() {
    let l = add()
    while (toks[p] && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v; l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { k: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw bad
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (isOp('(')) { p++; const e = cmp(); if (!isOp(')')) throw bad; p++; return e }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) throw bad
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw bad
        }
        return { k: 'call', fn: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const t2 = toks[p]
        if (!t2 || t2.t !== 'word') throw bad
        p++
        return { k: 'range', a: parseAddr(t.v), b: parseAddr(t2.v) }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { k: 'bool', v: true }
      if (u === 'FALSE') return { k: 'bool', v: false }
      return { k: 'ref', a: parseAddr(t.v) }
    }
    throw bad
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) { if (e.message === 'grammar') return null; throw e }
}

function misplaced(n, direct = false) {
  switch (n.k) {
    case 'range': return !direct
    case 'bin': return misplaced(n.l) || misplaced(n.r)
    case 'un': return misplaced(n.e)
    case 'call': return n.args.some((a) => misplaced(a, true))
    default: return false
  }
}

function cellsOf(n, out) {
  switch (n.k) {
    case 'ref': if (n.a) out.add(key(n.a)); break
    case 'range':
      if (n.a && n.b) {
        for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
          for (let r = Math.min(n.a.row, n.b.row); r <= Math.max(n.a.row, n.b.row); r++) out.add(c * 1000 + r)
      }
      break
    case 'bin': cellsOf(n.l, out); cellsOf(n.r, out); break
    case 'un': cellsOf(n.e, out); break
    case 'call': n.args.forEach((a) => cellsOf(a, out)); break
  }
}

// ---- evaluation
const asts = new Map()
const memo = new Map()
const busy = new Set()

function cellAst(k) {
  if (!asts.has(k)) {
    const c = cells.get(k)
    let ast = null
    if (c !== undefined && c[0] === '=') {
      ast = parse(c.slice(1))
      if (ast && misplaced(ast)) ast = { k: 'bad' }
    }
    asts.set(k, ast)
  }
  return asts.get(k)
}

function cellValue(k) {
  if (memo.has(k)) return memo.get(k)
  const c = cells.get(k)
  let v
  if (c === undefined || c === '') v = 0
  else if (c[0] === '=') {
    if (busy.has(k)) return err('#CYCLE!')
    busy.add(k)
    const ast = cellAst(k)
    v = !ast || ast.k === 'bad' ? err('#ERR!') : evalNode(ast)
    busy.delete(k)
  } else if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) v = Number(c)
  else if (ERRS.has(c)) v = err(c)
  else v = c
  if (typeof v === 'number' && !Number.isFinite(v)) v = err('#DIV/0!')
  memo.set(k, v)
  return v
}

function num(v) {
  if (isErr(v)) return v
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  return err('#VALUE!')
}
const fin = (x) => (Number.isFinite(x) ? x : err('#DIV/0!'))
const rank = (v) => (typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2)

function expand(n) {
  if (!n.a || !n.b) return [err('#REF!')]
  const out = []
  for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
    for (let r = Math.min(n.a.row, n.b.row); r <= Math.max(n.a.row, n.b.row); r++) out.push(cellValue(c * 1000 + r))
  return out
}

function evalNode(n) {
  switch (n.k) {
    case 'num': return fin(n.v)
    case 'bool': return n.v
    case 'ref': return n.a ? cellValue(key(n.a)) : err('#REF!')
    case 'range': return err('#ERR!')
    case 'un': {
      const x = num(evalNode(n.e))
      if (isErr(x)) return x
      return n.op === '-' ? -x : x
    }
    case 'bin': {
      const l = evalNode(n.l)
      if (isErr(l)) return l
      const r = evalNode(n.r)
      if (isErr(r)) return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        let d
        const rl = rank(l), rr = rank(r)
        if (rl !== rr) d = rl - rr
        else if (rl === 2) d = Number(l) - Number(r)
        else d = l < r ? -1 : l > r ? 1 : 0
        return { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
      }
      const a = num(l); if (isErr(a)) return a
      const b = num(r); if (isErr(b)) return b
      switch (n.op) {
        case '+': return fin(a + b)
        case '-': return fin(a - b)
        case '*': return fin(a * b)
        case '/': return b === 0 ? err('#DIV/0!') : fin(a / b)
        default: return fin(Math.pow(a, b))
      }
    }
    case 'call': return evalCall(n)
  }
}

function evalCall(n) {
  const { fn, args } = n
  const one = (a) => {
    if (a.k !== 'range') return evalNode(a)
    const vs = expand(a)
    const e = vs.find(isErr)
    if (e) return e
    return vs.length === 1 ? vs[0] : err('#VALUE!')
  }
  if (fn === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    const c = one(args[0])
    if (isErr(c)) return c
    if (typeof c === 'string') return err('#VALUE!')
    return one(args[c === true || (typeof c === 'number' && c !== 0) ? 1 : 2])
  }
  if (fn === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    const x = num(one(args[0]))
    return isErr(x) ? x : Math.abs(x)
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(fn)) return err('#NAME?')
  if (args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) {
    if (a.k === 'range') vals.push(...expand(a))
    else vals.push(evalNode(a))
  }
  const e = vals.find(isErr)
  if (e) return e
  if (fn === 'COUNT') return vals.filter((v) => typeof v === 'number').length
  const nums = []
  for (const v of vals) { const x = num(v); if (isErr(x)) return x; nums.push(x) }
  switch (fn) {
    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return Math.min(...nums)
    case 'MAX': return Math.max(...nums)
    default: return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
}

function show(v) {
  if (isErr(v)) return v.err
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  return v
}

const keys = [...cells.keys()].sort((a, b) => a - b)
let out = ''
for (const k of keys) {
  if (mode === 'values') out += `${name(k)}=${show(cellValue(k))}\n`
  else {
    const set = new Set()
    const ast = cellAst(k)
    if (ast && ast.k !== 'bad') cellsOf(ast, set)
    else if (ast && ast.k === 'bad') {
      const full = parse(cells.get(k).slice(1))
      cellsOf(full, set)
    }
    out += `${name(k)}:${[...set].sort((a, b) => a - b).map((x) => ' ' + name(x)).join('')}\n`
  }
}
process.stdout.write(out)
